import ast
src=open('threshold_wallet/service.py',encoding='utf-8').read()
tree=ast.parse(src)

def is_in(node, anc):
    # is node a lexical descendant of anc?
    for p in ast.walk(anc):
        if p is node:
            return True
    return False

class Checker(ast.NodeVisitor):
    def visit_FunctionDef(self, fn):
        locks=[n for n in ast.walk(fn) if isinstance(n, ast.With) and any(
            isinstance(it.context_expr, ast.Call)
            and getattr(it.context_expr.func,'attr','')=='_wallet_lock'
            for it in n.items)]
        # helpers that are pure-validation or intended outside-lock
        OUTSIDE_OK={'_thread_lock_for','_wallet_lock','create_wallet'}
        if not locks:
            self.generic_visit(fn); return
        for n in ast.walk(fn):
            if isinstance(n,(ast.Call,)) and isinstance(n.func, ast.Attribute):
                # self._store.X / self._emit / self._heal_wallet etc
                owner=None
                if isinstance(n.func.value, ast.Attribute) and isinstance(n.func.value.value, ast.Name) and n.func.value.value.id=='self':
                    owner=n.func.value.attr  # '_store'/'_audit'
                if owner in ('_store','_audit'):
                    if not any(is_in(n,w) for w in locks):
                        print(f"{fn.name}: {owner}.{n.func.attr} NOT in lock at line {n.lineno}")
                if isinstance(n.func.value, ast.Name) and n.func.value.id=='self' and n.func.attr in ('_emit','_heal_wallet','_get_wallet_or_404'):
                    if not any(is_in(n,w) for w in locks):
                        print(f"{fn.name}: self.{n.func.attr} NOT in lock at line {n.lineno}")
        self.generic_visit(fn)

Checker().visit(tree)
print("done")
EOF

