import ast
src=open('threshold_wallet/service.py',encoding='utf-8').read()
tree=ast.parse(src)
STATE_HELPERS={'_fetch_request_or_404','_expire_if_needed','_resolve_asset_commit_intent',
               '_recover_wallet_asset_commits','_recover_wallet','_activated_rotations',
               'get_share','get_wallet','share_sign'}
def descendants(n):
    for p in ast.walk(n): yield p
class C(ast.NodeVisitor):
    def visit_FunctionDef(self, fn):
        locks=[n for n in ast.walk(fn) if isinstance(n,ast.With) and any(
            isinstance(it.context_expr,ast.Call) and getattr(it.context_expr.func,'attr','')=='_wallet_lock'
            for it in n.items)]
        for n in ast.walk(fn):
            if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and n.func.attr in STATE_HELPERS:
                inside=any(n in set(descendants(w)) for w in locks)
                if not inside:
                    print(f"{fn.name}: self.{n.func.attr} called OUTSIDE lock line {n.lineno}")
        self.generic_visit(fn)
C().visit(tree)
print("helper-scan done")
EOF

